package com.array;

public class Array2D {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int b[][] = new int[3][2];
		
		for(int i=0; i<=b.length-1;i++) {
			for(int j=0; j<=b[i].length-1;j++) {
				System.out.print(b[i][j]);
			}
			System.out.println("");
		}

	}

}
